"import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { BookOpen, Target, Monitor, ArrowRight, Brain, TrendingUp } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { DashboardSkeleton } from "@/components/DashboardSkeleton";

interface QuizResult {
  id: string;
  course_id: string;
  score: number;
  total_questions: number;
  created_at: string;
  courses: { title: string; };
}

const Dashboard = () => {
  const [results, setResults] = useState<QuizResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [firstName, setFirstName] = useState<string>("");
  const navigate = useNavigate();

  const fetchResults = useCallback(async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        navigate("/auth");
        return;
      }

      const { data: profile } = await supabase
        .from("profiles")
        .select("first_name, name")
        .eq("id", user.id)
        .single();

      if (profile) {
        setFirstName(profile.first_name || profile.name || "Docteur");
      }

      const { data, error } = await supabase
        .from("quiz_results")
        .select(`id, course_id, score, total_questions, created_at, courses(title)`)
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(5);

      if (error) throw error;
      setResults(data || []);
    } catch (error) {
      toast.error("Erreur lors du chargement des données.");
    } finally {
      setLoading(false);
    }
  }, [navigate]);

  useEffect(() => { 
    fetchResults(); 
  }, [fetchResults]);

  if (loading) return <DashboardSkeleton />;

  const averageScore = results.length > 0 
    ? Math.round((results.reduce((acc, r) => acc + (r.score / r.total_questions) * 100, 0) / results.length)) 
    : 0;


